INSERT INTO records(id,country,system,data,version,updated_at)
  SELECT 'CAN-mrl','CAN','mrl','{"id":"CAN-mrl","country":"CAN","system":"mrl","batches":[],"projects":[{"id":"CAN-LRPS","buyer":"CAN","supplier":"Lockheed Martin (미국 FMS)","stage":"contract","model":"M142 HIMARS","qty":26,"amount":2600000000,"currency":"CAD","decisionYear":2026,"contractYear":2026,"deliveryStart":2029,"deliveryEnd":2034,"covers":1,"asOf":"2026-10-23","est":["deliveryEnd"],"text":"LRPS(L) 장거리 정밀타격(지상) 사업: 2026년 1월 미국 정부와 FMS 협정으로 M142 HIMARS 26대 도입. 늦어도 2029년 인도 시작, 2030년 초기 운용능력, 2034년 완전 운용능력 목표. 사업 전체 비용 추정 26억 캐나다달러(금액은 사업 전체 기준). 미 국무부 FMS 승인 통보 25-76(17.5억 달러). 인도 완료 연도는 완전 운용능력 연도(2034) 기준 추정. 캐나다는 기존 다연장로켓이 없어 신규 전력 수요를 이 계약이 채움","src":["can_lrps_dnd","can_lrps_army","can_lrps_fr"]}],"src":["can_lrps_dnd","can_lrps_army","can_lrps_fr"]}',1,strftime('%Y-%m-%dT%H:%M:%fZ','now')
  WHERE EXISTS (SELECT 1 FROM countries WHERE id='CAN') AND EXISTS (SELECT 1 FROM systems WHERE id='mrl')
    AND NOT EXISTS (SELECT 1 FROM records WHERE country='CAN' AND system='mrl') AND NOT EXISTS (SELECT 1 FROM records WHERE id='CAN-mrl');
