  version=version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now')
  WHERE country='CAN' AND system='mrl' AND NOT EXISTS (SELECT 1 FROM json_each(records.data,'$.projects') WHERE json_extract(value,'$.id')='CAN-LRPS');
